  const rec2 = (verdict, w3, w3dir) => ({ base: base2, x: 'F6', w: 'carries', z: 'r7', w2: 'carries', y: 'Φ9', dirs: ['←', '→'], ...(w3 ? { w3 } : {}), ...(w3dir ? { w3dir } : {}), verdict });
  said('B', 'Φ9', 'outranks', 'A', 'F6'); // the direct the other way round
