  said('A', 'F6', 'carries', 'C', 'r7'); said('C', 'r7', 'carries', 'B', 'Φ9'); // the chain F6 carries r7 · r7 carries Φ9
  const KEY3 = 'F6|carries|r7|carries|Φ9';
